    pvz::setattr(L_guest, SY("transport"), (L_ClientTransport).call(Args({SV("127.0.0.1"), pvz::getattr(pvz::getattr(L_host, SY("transport")), SY("port"))}, {{SY("identity"), pvz::getattr(L_guest, SY("identity"))}})));
    (void)(m_tcp_until(Args{L_host, L_guest, V::func([=, this](const Args& A) -> V { return py_and(V(py::in(pvz::getattr(L_guest, SY("peer_id")), pvz::getattr(pvz::getattr(L_host, SY("room")), SY("members")))), [&]() -> V { return V((py::m_get(pvz::getattr(L_guest, SY("view")), SV("mode")) == pm_teams::COOP)); }); })}));
